package com.crtc.app;
import android.app.*;import android.os.*;import android.graphics.Color;import android.content.*;import android.database.sqlite.*;import android.database.*;import android.view.*;import android.widget.*;import java.util.*;
/** Native Android entry point. No WebView or Trusted Web Activity is used. */
public final class MainActivity extends Activity {
 LinearLayout body; EventStore events; InventoryStore inventory; final int gold=Color.rgb(212,175,55);
 public void onCreate(Bundle b){super.onCreate(b);events=new EventStore(this);inventory=new InventoryStore(this);splash();}
 void splash(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setGravity(Gravity.CENTER);l.setBackgroundColor(Color.rgb(9,11,18));l.setPadding(48,48,48,96);TextView t=new TextView(this);t.setText("In memory of my father, Christopher Hale,\nwho tracked trucks in C++ before I ever tracked a deal.");t.setTextSize(17);t.setTextColor(gold);t.setGravity(Gravity.CENTER);l.addView(t,new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,0,1));ProgressBar p=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);p.setMax(100);p.setProgress(0);p.setProgressTintList(android.content.res.ColorStateList.valueOf(gold));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,(int)(4*getResources().getDisplayMetrics().density+0.5f));lp.setMargins(48,24,48,0);l.addView(p,lp);setContentView(l);final Handler h=new Handler(Looper.getMainLooper());final long start=android.os.SystemClock.uptimeMillis();h.post(new Runnable(){public void run(){int v=(int)Math.min(100,(android.os.SystemClock.uptimeMillis()-start)*100/3500);p.setProgress(v);if(v>=100)analyze();else h.postDelayed(this,50);}});}
 void base(String title,String help){ScrollView s=new ScrollView(this);s.setBackgroundColor(Color.rgb(9,11,18));body=new LinearLayout(this);body.setPadding(32,28,32,28);body.setOrientation(LinearLayout.VERTICAL);s.addView(body);add(title,30,gold);add(help,15,Color.LTGRAY);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(9,11,18));root.addView(s,new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,0,1));LinearLayout n=new LinearLayout(this);n.setBackgroundColor(Color.rgb(9,11,18));final int bh=(int)(56*getResources().getDisplayMetrics().density+0.5f);for(String x:new String[]{"Analyze","Inventory","Cross-list","Plans","Settings"}){Button b=new Button(this);b.setText(x);b.setTextSize(12);b.setMinHeight(0);b.setMinimumHeight(0);b.setOnClickListener(v->{if(x.equals("Analyze"))analyze();else if(x.equals("Inventory"))inventory();else if(x.equals("Cross-list"))cross(null);else if(x.equals("Plans"))plans();else settings();});n.addView(b,new LinearLayout.LayoutParams(0,bh,1));}n.setOnApplyWindowInsetsListener(new View.OnApplyWindowInsetsListener(){public WindowInsets onApplyWindowInsets(View v,WindowInsets insets){int sb=Build.VERSION.SDK_INT>=30?insets.getInsets(WindowInsets.Type.systemBars()).bottom:insets.getSystemWindowInsetBottom();v.setPadding(v.getPaddingLeft(),v.getPaddingTop(),v.getPaddingRight(),sb);return insets;}});s.setOnApplyWindowInsetsListener(new View.OnApplyWindowInsetsListener(){public WindowInsets onApplyWindowInsets(View v,WindowInsets insets){int st=Build.VERSION.SDK_INT>=30?insets.getInsets(WindowInsets.Type.systemBars()).top:insets.getSystemWindowInsetTop();body.setPadding(32,28+st,32,28);return insets;}});root.addView(n,new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,LinearLayout.LayoutParams.WRAP_CONTENT));setContentView(root);events.record("screen_view","screen="+title);}
 void add(String x,float size,int c){TextView v=new TextView(this);v.setText(x);v.setTextSize(size);v.setTextColor(c);v.setPadding(5,7,5,12);body.addView(v);} LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setPadding(22,18,22,18);c.setOrientation(LinearLayout.VERTICAL);c.setBackgroundColor(Color.rgb(25,29,42));body.addView(c);return c;} EditText labeled(LinearLayout parent,String label,String value){TextView t=new TextView(this);t.setText(label);t.setTextSize(13);t.setTextColor(gold);t.setPadding(5,12,5,2);parent.addView(t);EditText e=new EditText(this);e.setHint(label);e.setText(value);e.setTextColor(Color.WHITE);e.setHintTextColor(Color.GRAY);parent.addView(e);return e;} Button go(String x){Button b=new Button(this);b.setText(x);b.setTextColor(Color.BLACK);b.setBackgroundColor(gold);return b;} double num(EditText e){try{double x=Double.parseDouble(e.getText().toString());return x>=0&&Double.isFinite(x)?x:0;}catch(Exception z){return 0;}} String money(double x){return String.format(Locale.US,"$%,.2f",x);}
 void analyze(){base("Analyze a deal","Enter what you can buy it for and what you expect to sell it for.");LinearLayout c=card();EditText cost=labeled(c,"Purchase / hammer price","0");EditText resale=labeled(c,"Expected resale price","0");EditText fee=labeled(c,"Resale fee %","13");EditText premium=labeled(c,"Buyer premium %","18");TextView out=new TextView(this);out.setTextSize(18);out.setTextColor(Color.WHITE);c.addView(out);Button b=go("ANALYZE DEAL");b.setOnClickListener(v->{Deal d=Deal.calc(num(cost),num(resale),num(fee),num(premium));out.setText(d.verdict+"\nProfit: "+money(d.profit)+" • ROI: "+(Double.isInfinite(d.roi)?"∞":String.format("%.1f%%",d.roi))+"\nTrue cost "+money(d.cost)+" • Net resale "+money(d.net));events.record("deal_analyzed","cost="+cost.getText()+"|resale="+resale.getText()+"|verdict="+d.verdict+"|roi="+d.roi);});c.addView(b);}
 void inventory(){base("Inventory","Save items here after you decide to buy. Tap an item to draft an eBay Sandbox listing.");LinearLayout c=card();EditText name=labeled(c,"Item name","");EditText cost=labeled(c,"Cost basis","0");EditText price=labeled(c,"List price","0");Button b=go("SAVE ITEM");b.setOnClickListener(v->{inventory.add(name.getText().toString().isEmpty()?"Untitled":name.getText().toString(),num(cost),num(price));inventory();});c.addView(b);for(Item i:inventory.all()){TextView t=new TextView(this);t.setText(i.name+"\nCost "+money(i.cost)+" • List "+money(i.price));t.setTextColor(Color.WHITE);t.setTextSize(16);t.setPadding(15,15,15,15);t.setOnClickListener(v->cross(i));body.addView(t);}}
 void cross(Item i){base("eBay sandbox cross-list","Save a local draft, then publish only when Sandbox credentials and policies are configured.");LinearLayout c=card();EditText title=labeled(c,"Listing title",i==null?"":i.name);EditText price=labeled(c,"Price",i==null?"0":String.valueOf(i.price));TextView status=new TextView(this);status.setTextColor(Color.LTGRAY);c.addView(status);Button d=go("SAVE SANDBOX DRAFT");d.setOnClickListener(v->{events.record("ebay_draft","title="+title.getText()+"|price="+price.getText());status.setText("Draft saved locally. Review it, then publish to eBay Sandbox.");});c.addView(d);Button p=go("PUBLISH TO SANDBOX");p.setOnClickListener(v->{status.setText("Sandbox-only publish is blocked until the user token, location, and policies from ebay_sell.py are configured. No production endpoint exists in this app.");events.record("ebay_publish","result=configuration_needed");});c.addView(p);}
 void plans(){base("Choose a plan","Subscriptions unlock monthly analysis limits. Free requires verified email.");LinearLayout c=card();for(String x:new String[]{"Free — $0 • 5 analyses/month","Starter — $25 • 50 analyses","Pro • Most Popular — $50 • 250 analyses","Business — $100 • 1,000 analyses, 3 seats","Enterprise — $200 • 5,000 analyses, 10 seats"}){Button b=go(x);b.setOnClickListener(v->Toast.makeText(this,"Register this subscription in Play Console to enable billing test purchases.",Toast.LENGTH_LONG).show());c.addView(b);}}
 void settings(){base("Settings & privacy","Holy Grail thresholds are editable. The app requests only Internet access.");LinearLayout c=card();EditText roi=labeled(c,"Holy Grail minimum ROI %","40");EditText profit=labeled(c,"Minimum profit $","15");EditText max=labeled(c,"Maximum buy cost $","100");EditText fee=labeled(c,"Default resale fee %","13");EditText premium=labeled(c,"Default buyer premium %","18");Button b=go("SAVE SETTINGS");b.setOnClickListener(v->{getPreferences(0).edit().putString("holy_grail","roi="+roi.getText()+"|profit="+profit.getText()+"|max="+max.getText()+"|fee="+fee.getText()+"|premium="+premium.getText()).apply();Toast.makeText(this,"Settings saved",Toast.LENGTH_SHORT).show();});c.addView(b);add("Privacy: Appraze stores deal inputs, verdicts, screen views, and publishing outcomes on this device as structured usage events. This build does not share ad data. Usage-data collection is disclosed here.",14,Color.LTGRAY);}
}
class Deal{double cost,net,profit,roi;String verdict;static Deal calc(double cost,double resale,double fee,double premium){Deal d=new Deal();d.cost=cost*(1+premium/100);d.net=resale*(1-fee/100);d.profit=d.net-d.cost;d.roi=d.cost>0?d.profit/d.cost*100:d.profit>0?Double.POSITIVE_INFINITY:0;d.verdict=d.roi>=60?"STRONG BUY":d.roi>=40?"BUY":d.roi>=20?"AT CEILING":d.roi>=5?"BORDERLINE":"PASS";return d;}}
class Item{String name;double cost,price;Item(String n,double c,double p){name=n;cost=c;price=p;}} class EventStore extends SQLiteOpenHelper{EventStore(Context x){super(x,"events.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE events(type TEXT,payload TEXT,created_at INTEGER)");}public void onUpgrade(SQLiteDatabase d,int a,int b){}void record(String t,String p){ContentValues v=new ContentValues();v.put("type",t);v.put("payload",p);v.put("created_at",System.currentTimeMillis());getWritableDatabase().insert("events",null,v);}} class InventoryStore extends SQLiteOpenHelper{InventoryStore(Context x){super(x,"inventory.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE inventory(name TEXT,cost REAL,price REAL)");}public void onUpgrade(SQLiteDatabase d,int a,int b){}void add(String n,double co,double pr){ContentValues v=new ContentValues();v.put("name",n);v.put("cost",co);v.put("price",pr);getWritableDatabase().insert("inventory",null,v);}ArrayList<Item>all(){ArrayList<Item>x=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT name,cost,price FROM inventory ORDER BY rowid DESC",null);while(c.moveToNext())x.add(new Item(c.getString(0),c.getDouble(1),c.getDouble(2)));c.close();return x;}}
